import java.util.*;import java.util.function.*;import java.nio.file.Path;
import java.util.stream.*;
public class Study{static {if(java.lang.System.getProperty("course.initializer.marker")!=null){try{java.nio.file.Files.writeString(java.nio.file.Path.of(java.lang.System.getProperty("course.initializer.marker")),"student initializer executed");}catch(java.io.IOException e){throw new java.lang.RuntimeException(e);}throw new java.lang.IllegalStateException("initializer sentinel");}}record Item(int id,String name){}public static Object create(int id,String name){return new Item(id,name);}public static Object[]array(Object...values){return Arrays.copyOf(values,values.length,Item[].class);}public static Object[]distinct(Object[]input){return Arrays.stream((Item[])input).distinct().toArray(Item[]::new);}public static int id(Object value){return ((Item)value).id();}public static String name(Object value){return ((Item)value).name();}}
